import {packActor,restoreActor} from './actor-state.js';
import * as T from './vendor/three.module.js';
import {modelActor,witchMaterial} from './models.js';
import {dropFor,respawnCandidates} from './ecology.js';
export function deepForest({scene,camera,free,rand,resetMotion}){
const mobs=[],drops=[],hostileShots=[];let inside=false,time=0;
const entry=new T.Vector3(240,0,-45),gate=new T.Vector3(35,0,-100),witchHome=new T.Vector3(292,0,-184);
function spawn(species,x,z){const n=modelActor(scene,[],x,z,species==='wolf'?1.15:species==='hare'?.55:.6,species==='wolf'?true:species);Object.assign(n,{species,id:'deep-'+species+'-'+mobs.length,generation:0,maxHp:species==='wolf'?35:species==='hare'?10:5,hp:species==='wolf'?35:species==='hare'?10:5,home:new T.Vector3(x,0,z),target:new T.Vector3(x,0,z),timer:0,cooldown:0,aggro:null});mobs.push(n);return n}
for(const [x,z] of [[211,-69],[265,-69],[191,-98],[236,-91],[285,-98],[207,-123],[259,-125],[191,-154],[236,-160],[274,-159]]){spawn('hare',x,z);spawn('wolf',x-3,z-3);spawn('wolf',x+3,z+2)}
for(const [x,z] of [[220,-80],[278,-115],[225,-140],[195,-180],[270,-180]])spawn('raven',x,z);
const witch=modelActor(scene,[],witchHome.x,witchHome.z,1.9,false,'witch');Object.assign(witch,{species:'witch',id:'witch',maxHp:200,hp:200,generation:0,home:witchHome.clone(),cooldown:2,target:witchHome.clone()});witch.g.visible=false;const hat=new T.Mesh(new T.ConeGeometry(.4,.65,7),witchMaterial('шляпа'));hat.position.y=1.95;witch.g.add(hat);const brim=new T.Mesh(new T.CylinderGeometry(.44,.44,.06,9),hat.material);brim.position.y=1.65;witch.g.add(brim);
function portal(pos,color){const group=new T.Group();group.position.copy(pos);scene.add(group);const material=new T.MeshStandardMaterial({color:0x314647});for(const x of [-2,2]){const m=new T.Mesh(new T.BoxGeometry(.65,4,.7),material);m.position.set(x,2,0);group.add(m)}const top=new T.Mesh(new T.BoxGeometry(4.7,.65,.8),material);top.position.y=4;group.add(top);const glow=new T.Mesh(new T.TorusGeometry(1.4,.035,5,32),new T.MeshBasicMaterial({color,transparent:true,opacity:.65}));glow.position.y=1.8;group.add(glow);return group}const villagePortal=portal(gate,0x6fbcc3);villagePortal.rotation.y=Math.PI/2;portal(entry,0x9fb8c1);
function portalNear(){return Math.hypot(camera.position.x-(inside?entry.x:gate.x),camera.position.z-(inside?entry.z:gate.z))<3.6}
function travel(p){inside=!inside;camera.position.set(inside?entry.x:31,1.7,inside?entry.z-5:gate.z);resetMotion();for(const n of mobs)n.aggro=null;for(const b of hostileShots)scene.remove(b.m);hostileShots.length=0;if(inside&&p.stage==='forest')p.stage='carcasses';document.querySelector('#location').textContent=inside?'Глубины Темнолесья':'Темнолесье';}
function can(x,z){return inside?x>180&&x<300&&z< -39&&z> -198:Math.abs(x)<39&&z<15&&z> -119}
function walk(n,target,speed,dt){const dx=target.x-n.g.position.x,dz=target.z-n.g.position.z,d=Math.hypot(dx,dz);if(d<.25)return;n.heading=Math.atan2(dx,dz);const step=Math.min(d,speed*dt),x=n.g.position.x+dx/d*step,z=n.g.position.z+dz/d*step;if(x<181||x>299||z> -40||z< -197)return;if(free(x,z,.35))n.g.position.set(x,0,z);else if(free(x,n.g.position.z,.35))n.g.position.x=x;else if(free(n.g.position.x,z,.35))n.g.position.z=z;else n.timer=0}
function spawnDrop(id,pos){const g=new T.Group();g.position.copy(pos);scene.add(g);const m=new T.Mesh(id==='carcass'?new T.BoxGeometry(.36,.2,.22):new T.ConeGeometry(.11,.33,4),new T.MeshStandardMaterial({color:id==='carcass'?0xc39183:0xeee0b6,emissive:id==='carcass'?0x6e3730:0x77684a,emissiveIntensity:.7}));g.add(m);if(id==='carcass'){const h=new T.Mesh(new T.BoxGeometry(.14,.14,.14),m.material);h.position.set(.22,.05,0);g.add(h)}const ring=new T.Mesh(new T.RingGeometry(.18,.32,16),new T.MeshBasicMaterial({color:0xcde1ac,transparent:true,opacity:.4,side:T.DoubleSide}));ring.rotation.x=-Math.PI/2;ring.position.y=-.25;g.add(ring);drops.push({id,g,phase:rand()*7})}
function killed(n){if(!mobs.includes(n))return;const item=dropFor(n.species,rand());if(item)spawnDrop(item,n.g.position);for(const dead of respawnCandidates(mobs,n)){let point=dead.home.clone();for(let i=0;i<20;i++){const a=rand()*Math.PI*2,r=1+rand()*2.5,trial=dead.home.clone().add(new T.Vector3(Math.cos(a)*r,0,Math.sin(a)*r));if(free(trial.x,trial.z,.5)){point=trial;break}}dead.g.position.copy(point);dead.g.visible=true;dead.hp=dead.maxHp;dead.hit=false;dead.aggro=null;dead.target.copy(point);dead.generation++;dead.timer=1;dead.cooldown=1;}}
function tick(dt,{onDamage,p,pickup}){if(!inside)return;time+=dt;if(p.stage==='witch'&&p.rewards.includes('rabbit-quest')&&!mobs.includes(witch)){witch.g.visible=true;mobs.push(witch)}for(const n of mobs){if(n.hp<=0)continue;n.cooldown=Math.max(0,n.cooldown-dt);const distance=Math.hypot(n.g.position.x-camera.position.x,n.g.position.z-camera.position.z);if(n.species==='witch'){if(distance<20&&n.cooldown===0){n.cooldown=1.8+rand()*.6;const large=rand()<.15,m=new T.Mesh(new T.SphereGeometry(large?.28:.12,10,8),new T.MeshBasicMaterial({color:large?0x73ff2f:0xff732c}));m.position.copy(n.g.position).add(new T.Vector3(0,1.4,0));const v=camera.position.clone().sub(m.position).normalize().multiplyScalar(large?8:11);scene.add(m);hostileShots.push({m,v,damage:large?25:15,age:0})}continue}if(n.species==='wolf'){if(!n.aggro&&distance<7)n.aggro=camera.position.clone();if(n.aggro&&camera.position.distanceTo(n.aggro)>24)n.aggro=null;if(n.aggro){walk(n,camera.position,3.4,dt);if(distance<1.65&&n.cooldown===0&&camera.position.y<2.6&&[.25,.5,.75].every(t=>free(n.g.position.x+(camera.position.x-n.g.position.x)*t,n.g.position.z+(camera.position.z-n.g.position.z)*t,.05))){n.cooldown=1.3;onDamage(14)}n.update();continue}}n.timer-=dt;if(n.timer<=0){n.timer=2+rand()*4;for(let i=0;i<15;i++){const x=n.home.x+(rand()-.5)*6,z=n.home.z+(rand()-.5)*6;if(free(x,z,.4)){n.target.set(x,0,z);break}}}walk(n,n.target,n.species==='hare'?1.3:.9,dt);n.update()}
for(let i=drops.length-1;i>=0;i--){const d=drops[i];d.g.position.y=.45+Math.sin(time*2+d.phase)*.10;d.g.rotation.y=time*1.6+d.phase;if(d.g.position.distanceTo(camera.position)<1.7&&pickup(d.id)){scene.remove(d.g);d.g.traverse(m=>{if(m.isMesh){m.geometry.dispose();m.material.dispose()}});drops.splice(i,1)}}
for(let i=hostileShots.length-1;i>=0;i--){const b=hostileShots[i],old=b.m.position.clone();b.m.position.addScaledVector(b.v,dt);b.age+=dt;const hit=new T.Line3(old,b.m.position).closestPointToPoint(camera.position,true,new T.Vector3()).distanceTo(camera.position)<.5;if(hit)onDamage(b.damage,'magic');if(hit||b.age>5||!free(b.m.position.x,b.m.position.z,.05)){scene.remove(b.m);b.m.geometry.dispose();b.m.material.dispose();hostileShots.splice(i,1)}}}
function snapshot(){return {inside,time,witchActive:mobs.includes(witch),witch:packActor(witch),mobs:mobs.map(packActor),drops:drops.map(d=>({id:d.id,position:d.g.position.toArray(),phase:d.phase})),shots:hostileShots.map(b=>({position:b.m.position.toArray(),velocity:b.v.toArray(),damage:b.damage,age:b.age,large:b.damage===25}))}}
function restore(state){inside=state.inside;time=state.time;const index=mobs.indexOf(witch);if(index>=0)mobs.splice(index,1);restoreActor(witch,state.witch);if(state.witchActive)mobs.push(witch);for(const data of state.mobs){const n=mobs.find(n=>n.id===data.id);restoreActor(n,data)}for(const d of drops){scene.remove(d.g);d.g.traverse(n=>{if(n.isMesh){n.geometry.dispose();n.material.dispose()}})}drops.length=0;for(const d of state.drops){spawnDrop(d.id,new T.Vector3().fromArray(d.position));drops.at(-1).phase=d.phase}for(const b of hostileShots){scene.remove(b.m);b.m.geometry.dispose();b.m.material.dispose()}hostileShots.length=0;for(const b of state.shots){const m=new T.Mesh(new T.SphereGeometry(b.large?.28:.12,10,8),new T.MeshBasicMaterial({color:b.large?0x73ff2f:0xff732c}));m.position.fromArray(b.position);scene.add(m);hostileShots.push({m,v:new T.Vector3().fromArray(b.velocity),damage:b.damage,age:b.age})}document.querySelector('#location').textContent=inside?'Глубины Темнолесья':'Темнолесье'}
return {get inside(){return inside},mobs,drops,witch,snapshot,restore,portalNear,travel,can,killed,tick,reset(){inside=false;for(const n of mobs)n.aggro=null;document.querySelector('#location').textContent='Темнолесье'}};
}
